from lib import *
S = SS('l56')
steps = [
    step("源仓库:3 次提交,3,003 个松散对象(最近一批提交没打包)加 1 个 pack(里面 4,525 个对象,388 KiB),松散对象占 11.80 MiB。git count-objects -vH 给出 count: 3003、size: 11.80 MiB、in-pack: 4525、size-pack: 388.06 KiB。用它来测四种本地 clone。", t=tl(S(1)), mark=lidx(S(1), 'count: 3003', 'in-pack: 4525'), done=lidx(S(1), 'size: 11.80 MiB', 'size-pack'), kv=KV([['松散对象', '3,003 个,11.8 MiB'], ['pack', '1 个,388 KiB,4,525 个对象']], ['松散对象'])),
    step("四种本地 clone(耗时是 3 次中位数,含检出工作区):默认的 git clone /路径 1977 ms,松散对象和 pack 的链接数都是 2——clone 里的文件和源仓库的是同一个 inode(硬链接),clone 的 objects 目录额外占 0.0 MB;--no-hardlinks 1103 ms,链接数 1(真的复制了文件),额外占 12.2 MB;file:///路径 795 ms,没有松散对象、只有 1 个 pack(走的是正常的 fetch 协议,把对象重新打包),额外 0.7 MB;--shared 729 ms,clone 里没有任何对象文件,只有一个 alternates,额外 0.0 MB。注意:在这台 macOS APFS 上硬链接的 clone 反而最慢(要创建 3003 个硬链接),省的是磁盘而不是时间;file:// 因为把对象打成一个 pack,文件数少所以最快。", t=tl(S(2)), mark=lidx(S(2), 'git clone /路径(默认,本地路径)', 'git clone --shared /路径'), done=lidx(S(2), 'git clone --no-hardlinks /路径', 'git clone file:///路径', '“objects 额外磁盘”'), b=bars([['默认(硬链接)', 1977, '1977 ms'], ['--no-hardlinks', 1103, '1103 ms'], ['file://', 795, '795 ms'], ['--shared', 729, '729 ms']], 1977, mark=[0], done=[1, 2, 3]), kv=KV([['默认(路径)', '硬链接:0 MB 额外磁盘,但创建链接要时间'], ['--no-hardlinks', '真复制:12.2 MB'], ['file://', '走 fetch 协议,重新打包成 1 个 pack'], ['--shared', '不复制,用 alternates 指向源']], ['默认(路径)'])),
    step("file:// 的 clone 里 .git/objects 下只有 info 和 pack(没有 ?? 目录的松散对象),pack 目录里是新生成的 .idx/.pack/.rev;而路径方式的 clone 保持了源仓库的松散对象目录结构。remote.origin.url 指向源仓库(…/l56src),objects/info 下有 packs 文件。", t=tl(S(3)), mark=lidx(S(3), 'pack-9d5ddcc0fd80'), done=lidx(S(3), 'info pack', 'packs', 'l56src'), kv=KV([['file://', '新生成一个 pack'], ['路径', '保持松散对象目录结构'], ['remote.origin.url', '都指向源仓库']], ['file://'])),
    step("硬链接的 clone 不受源仓库 gc 影响;--shared 的 clone 会被源仓库的清理弄坏。--shared 的 clone 里 objects/info/alternates 记着源仓库的 objects 路径,自己的 objects 下只有 info 和 pack(没有对象)。然后在源仓库里把最新的提交永远删掉(reset --hard HEAD~1、清空 reflog、gc --prune=now),源仓库只剩 2 个提交。硬链接的 clone:git fsck 没有输出(完整),git log 仍能看到三个提交(它有自己的文件链接,源仓库删文件不影响内容);--shared 的 clone:git fsck 报 error: refs/heads/main: invalid sha1 pointer…,git log 报 fatal: bad object HEAD——对象只在源仓库里,被清理了就没了。", t=tl(S(4)), mark=lidx(S(4), 'invalid sha1 pointer', 'bad object HEAD', 'alternates'), done=lidx(S(4), '源仓库现在的提交数: 2', '无输出:完整', 'bfb737a 提交 3'), kv=KV([['硬链接', '文件独立存在,源仓库删除不影响'], ['--shared', '依赖源仓库的对象库'], ['风险', '源仓库 gc/prune 会弄坏 shared clone']], ['风险'])),
]
A = mkarti('l56', 56, 'Git,本地 clone,硬链接,alternates,--shared,真实验证,动画演示',
    '实测四种本地 clone:路径方式默认硬链接 .git/objects(链接数 2,额外磁盘 0 MB,但在 APFS 上要创建 3003 个链接,耗时 1977 ms 反而最慢);--no-hardlinks 真复制(12.2 MB,1103 ms);file:// 走 fetch 协议重新打包成 1 个 pack(795 ms);--shared 用 alternates 指向源仓库(729 ms,0 MB),源仓库 prune 后 shared clone 的 fsck 报 invalid sha1 pointer。',
    '在本机 git clone 一个本地仓库时,git 其实不是复制对象而是做硬链接。--no-hardlinks、file://、--shared 各自又做了什么?占多少磁盘、快不快、安不安全?这篇用三千多个松散对象的仓库逐种实测。',
    [('0.0 vs 12.2 MB', '硬链接 clone 与 --no-hardlinks clone 在 .git/objects 上额外占用的磁盘'), ('1977 ms', '硬链接 clone 的耗时——在 macOS APFS 上反而比真复制(1103 ms)慢'), ('bad object HEAD', '源仓库把对象 prune 之后,--shared clone 的 git log 的报错')],
    [('四种方式', '<p>本地路径 clone 默认把源仓库 <code>.git/objects</code> 下的文件做硬链接(链接数变成 2);<code>--no-hardlinks</code> 真复制;<code>file://</code> 走与远程相同的协议,把对象重新打包成一个 pack,不用链接;<code>--shared</code> 完全不复制,在 <code>objects/info/alternates</code> 里记下源仓库的对象目录。</p>'),
     ('磁盘与时间', '<p>硬链接和 shared 不额外占对象的磁盘空间,真复制占 12.2 MB。但硬链接在 APFS 上要创建几千个链接,比真复制还慢;file:// 因为把松散对象打成一个 pack,文件少,最快。</p>'),
     ('两种 clone 的结构', '<p>file:// 的 clone 的 <code>.git/objects</code> 里只有 <code>info</code> 和 <code>pack</code>,没有松散对象目录;路径方式保持源仓库的结构。</p>'),
     ('安全性', '<p>硬链接的文件在源仓库删除后仍然存在,clone 是自给自足的。<code>--shared</code> 的 clone 依赖源仓库的对象:源仓库 gc/prune 掉的对象,shared clone 里也就没了,<code>fsck</code> 报 <code>invalid sha1 pointer</code>。所以 shared 只适合源仓库不会清理的场合(如参考仓库、CI 缓存)。</p>')],
    steps,
    [ENV_I_GIT + '。源仓库由脚本生成(约 7,500 个小文件的三次提交,最后一次的 3,003 个对象保持松散);耗时是 3 次中位数(含检出工作区);磁盘用 du -sk 统计 .git/objects,源与 clone 放在同一次 du 里使硬链接只算一次;文件系统是 APFS',
     '没有验证:Linux ext4/xfs 上硬链接的耗时(预期更快,没有实测);--reference 与 --dissociate;git gc 对 alternates 的保护;跨文件系统 clone 时硬链接失败自动退回复制;git clone --local 的显式写法'],
    '本地 clone')
